    # Identify the grid-line color.
    sep = None
    for color in range(10):
        if sum(all(v == color for v in row) for row in grid) >= 2:
            sep = color
            break

    sep_rows = [r for r in range(h) if all(v == sep for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]
    rb = [-1] + sep_rows + [h]
    cb = [-1] + sep_cols + [w]
    bands = [(rb[i] + 1, rb[i + 1]) for i in range(len(rb) - 1)]
    tiles = [(cb[i] + 1, cb[i + 1]) for i in range(len(cb) - 1)]

    # The pattern is the non-background shape in a tile other than the first.
    pattern = None
    for r0, r1 in bands:
        for c0, c1 in tiles[1:]:
            cells = {(r - r0, c - c0)
                     for r in range(r0, r1)
                     for c in range(c0, c1)
                     if grid[r][c] not in (0, sep)}
            if cells:
                pattern = cells
                break
        if pattern:
            break

    if not pattern:
        return grid

    out = [row[:] for row in grid]
    for r0, r1 in bands:
        # The color for this band is given by its object in the first tile.
        c0, c1 = tiles[0]
        colors = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1)
                  if grid[r][c] not in (0, sep)]
        if not colors:
            continue
        color = colors[0]

